llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "Lamivudine, a polar cytidine nucleoside analog, has an absolute oral bioavailability of 86–88% in HIV patients, demonstrating that small hydrophilic nucleosides can be very well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Emtricitabine, a closely related cytidine nucleoside analog, has a mean absolute oral bioavailability of 93%, further supporting high oral absorption for this nucleoside class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Zalcitabine (dideoxycytidine) has an oral bioavailability of 88% in humans, another nucleoside analog with high systemic exposure after oral dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Cladribine, a purine 2'-deoxyribonucleoside analog, has an estimated oral bioavailability of about 45.6% from tablets, still well above the 20% threshold and relevant to the purine nucleoside query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Temozolomide, a heterocyclic drug with very high transfer relevance, shows approximately 100% oral bioavailability, indicating that this evidence neighborhood is strongly associated with high oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Didanosine under fed conditions had a bioavailability of 0.17–0.19, below 20%, but this is attributed to acid lability and food effects of the dideoxyinosine scaffold and is not representative of the more acid-stable carbocyclic guanine query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F >= 20%) because multiple high-transfer nucleoside analogs—lamivudine, emtricitabine, zalcitabine, and cladribine—show oral bioavailability from about 45% to 93%, and the query's carbocyclic guanine scaffold is expected to be more acid-stable than didanosine. The only sub-20% values come from fed didanosine and are not representative of this scaffold.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the exact carbocyclic guanine nucleoside query.",
    "The closest evidence is from other nucleoside analogs rather than the identical scaffold, leaving some uncertainty about transporter and permeability behavior.",
    "Didanosine fed-state data highlight food/acid lability effects that may not transfer to the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

